import { css } from "@styled-system/css"
import { createStyleContext } from "@styled-system/jsx"
import { X } from "lucide-react"
import { Dialog } from "radix-ui"
import { forwardRef } from "react"

import { recipe } from "./recipe"

const { withContext, withRootProvider } = createStyleContext(recipe)

export const Root = withRootProvider(Dialog.Root)

export const Portal = withContext(Dialog.Portal, "portal")

export const Overlay = withContext(Dialog.Overlay, "overlay")

export const Header = withContext("div", "header")

const CloseIcon = withContext(Dialog.Close, "close")

export const Close = Dialog.Close //pure logic for close dialog

export const ContentPrimitive = forwardRef<
  React.ElementRef<typeof Dialog.Content>,
  React.ComponentPropsWithoutRef<typeof Dialog.Content> & {
    closeIcon?: boolean
  }
>(({ children, closeIcon = true, ...props }, ref) => (
  <Portal>
    <Overlay />
    <Dialog.Content ref={ref} {...props}>
      {children}
      {closeIcon && (
        <CloseIcon aria-label="Close Dialog">
          <X />
          <span className={css({ srOnly: true })}>Close</span>
        </CloseIcon>
      )}
    </Dialog.Content>
  </Portal>
))

export const Content = withContext(ContentPrimitive, "content")

export const Trigger = withContext(Dialog.Trigger, "trigger")

export const Footer = withContext("div", "footer")

export const Title = withContext(Dialog.Title, "title")

export const Description = withContext(Dialog.Description, "description")

import { sva } from "@styled-system/css"

export const recipe = sva({
  slots: [
    "root",
    "trigger",
    "portal",
    "overlay",
    "close",
    "content",
    "header",
    "footer",
    "title",
    "description",
  ],
  base: {
    overlay: {
      position: "fixed",
      inset: "0",
      bg: "layer.overlay",
    },
    content: {
      bg: "layer.floating",
      color: "foreground",
      border: "input",
      borderRadius: "md",
      position: "fixed",
      top: "[50%]",
      left: "[50%]",
      transform: "translate(-50%,-50%)",
      width: "full",
      maxWidth: "[32rem]",
      maxHeight: "[85vh]",
      zIndex: "1000",
      padding: "4",
      overflow: "auto",
      "&[data-state=open]": {
        animationName: "contentShow",
        animationDuration: "slow",
      },

      "&[data-state=closed]": {
        animationName: "fadeOut",
        animationDuration: "slow",
      },
    },
    close: {
      position: "absolute",
      right: "4",
      top: "4",
      rounded: "sm",
      opacity: "0.7",
      transition: "opacity",
      cursor: "pointer",
      _hover: {
        opacity: "1",
      },

      _disabled: {
        pointerEvents: "none",
      },
    },
    header: {
      display: "flex",
      flexDirection: "column",
      gap: "1.5",
      color: "foreground.emphasized",
      textStyle: "heading2",
    },
    footer: {
      display: "flex",
      flexDirection: "column-reverse",
      color: "foreground.muted",
    },
    title: {
      textStyle: "heading1",
    },
    description: {
      textStyle: "body1",
      color: "foreground",
    },
  },
})

import { cn } from "@utils/cn"
import { X } from "lucide-react"
import { Dialog } from "radix-ui"
import { forwardRef } from "react"

import { dialog } from "./styles"

const styles = dialog()

export const Root = Dialog.Root

export const Portal = Dialog.Portal

export const Overlay = forwardRef<
  React.ElementRef<typeof Dialog.Overlay>,
  React.ComponentPropsWithoutRef<typeof Dialog.Overlay>
>(({ className, ...props }, ref) => (
  <Dialog.Overlay
    ref={ref}
    className={cn(styles.overlay(), className)}
    {...props}
  />
))

Overlay.displayName = Dialog.Overlay.displayName

export const Header = forwardRef<HTMLDivElement, React.ComponentProps<"div">>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn(styles.header(), className)} {...props} />
  ),
)

Header.displayName = "DialogHeader"

const CloseIcon = forwardRef<
  React.ElementRef<typeof Dialog.Close>,
  React.ComponentPropsWithoutRef<typeof Dialog.Close>
>(({ className, children, ...props }, ref) => (
  <Dialog.Close ref={ref} className={cn(styles.close(), className)} {...props}>
    {children}
  </Dialog.Close>
))

CloseIcon.displayName = Dialog.Close.displayName

export const Close = Dialog.Close

export const ContentPrimitive = forwardRef<
  React.ElementRef<typeof Dialog.Content>,
  React.ComponentPropsWithoutRef<typeof Dialog.Content> & {
    closeIcon?: boolean
  }
>(({ children, className, closeIcon = true, ...props }, ref) => (
  <Portal>
    <Overlay />
    <Dialog.Content
      ref={ref}
      className={cn(styles.content(), className)}
      {...props}
    >
      {children}
      {closeIcon && (
        <CloseIcon aria-label="Close Dialog">
          <X />
          <span className="sr-only">Close</span>
        </CloseIcon>
      )}
    </Dialog.Content>
  </Portal>
))

ContentPrimitive.displayName = Dialog.Content.displayName

export const Content = ContentPrimitive

export const Trigger = forwardRef<
  React.ElementRef<typeof Dialog.Trigger>,
  React.ComponentPropsWithoutRef<typeof Dialog.Trigger>
>(({ className, ...props }, ref) => (
  <Dialog.Trigger
    ref={ref}
    className={cn(styles.trigger(), className)}
    {...props}
  />
))

Trigger.displayName = Dialog.Trigger.displayName

export const Footer = forwardRef<HTMLDivElement, React.ComponentProps<"div">>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn(styles.footer(), className)} {...props} />
  ),
)

Footer.displayName = "DialogFooter"

export const Title = forwardRef<
  React.ElementRef<typeof Dialog.Title>,
  React.ComponentPropsWithoutRef<typeof Dialog.Title>
>(({ className, ...props }, ref) => (
  <Dialog.Title
    ref={ref}
    className={cn(styles.title(), className)}
    {...props}
  />
))

Title.displayName = Dialog.Title.displayName

export const Description = forwardRef<
  React.ElementRef<typeof Dialog.Description>,
  React.ComponentPropsWithoutRef<typeof Dialog.Description>
>(({ className, ...props }, ref) => (
  <Dialog.Description
    ref={ref}
    className={cn(styles.description(), className)}
    {...props}
  />
))

Description.displayName = Dialog.Description.displayName
